UPDATE phrase_bindings
    SET marks = #{marks}, marks_asked_at = now()
  WHERE kb_id = #{kbId} AND phrase = #{phrase}
    AND subject_type_id IS NOT DISTINCT FROM #{subjectTypeId}
    AND object_type_id IS NOT DISTINCT FROM #{objectTypeId}
    AND object_is_value = #{objectIsValue}
    AND status = 'bound' AND decided_by = 'agent' AND marks IS NULL
    AND relation_type_id = #{relationTypeId} AND direction = #{direction}
